"use strict";
let DATA, selected;
const $=s=>document.querySelector(s);
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=v=>Array.isArray(v)?(v.length?v.join(" · "):"Not supplied"):(v??"Not supplied");
const badge=(text)=>`<span class="badge ${text==='Agree'?'agree':text==='Disagree'?'disagree':text==='Automatic proposal'?'proposal':text==='Review needed'?'review':''}">${esc(text)}</span>`;
function filtered(){const q=$('#search').value.trim().toLowerCase(),d=$('#district').value,p=$('#sample').value==='pilot';return DATA.restaurants.filter(x=>(!p||x.branch.pilot)&&(!d||x.branch.district===d)&&(!q||[x.branch.name_en,x.branch.name_zh,x.branch.address_en,x.branch.address_zh].join(' ').toLowerCase().includes(q)))}
function renderList(){const rows=filtered();$('#visible-count').textContent=`${rows.length} branches shown`;if(!rows.some(x=>x.branch.branch_id===selected))selected=rows[0]?.branch.branch_id;$('#restaurant-list').innerHTML=rows.length?rows.map(x=>`<button role="listitem" data-id="${esc(x.branch.branch_id)}" aria-current="${x.branch.branch_id===selected}"><strong>${esc(x.branch.name_en)}</strong><small>${esc(x.branch.name_zh!==x.branch.name_en?x.branch.name_zh+' · ':'')}${esc(x.branch.district)}</small></button>`).join(''):'<p class="empty">No sampled branch matches these filters.</p>';$('#restaurant-list').querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=b.dataset.id;renderList()});renderDetail(rows.find(x=>x.branch.branch_id===selected))}
function renderDetail(x){if(!x){$('#detail').innerHTML='<p class="empty">Choose a different name or district.</p>';return}const b=x.branch;const value=(src,key)=>{if(src==='FEHD')return {name:b.aliases,address:b.addresses,phone:null,category:b.licence_types,opening_hours:null,operating_status:null}[key];const r=x.sources[src].record;if(!r)return null;return {name:r.aliases,address:r.addresses,phone:r.phones,category:r.category_raw,opening_hours:r.opening_hours,operating_status:r.operating_status}[key]};const row=(key,label)=>`<tr><th scope="row">${label}</th>${['FEHD','OSM','Overture'].map(src=>`<td>${esc(pretty(value(src,key)))}</td>`).join('')}</tr>`;$('#detail').innerHTML=`<p class="eyebrow">${esc(b.district)} · ${b.pilot?'PILOT':'PROVISIONAL MAIN SAMPLE'}</p><h2>${esc(b.name_en)}</h2><p class="subtitle">${esc(b.name_zh!==b.name_en?b.name_zh+' · ':'')}${esc(b.branch_id)} · Licence ${esc(b.licence_ids.join(', '))}</p><div class="table-wrap"><table><thead><tr><th>Observed field</th><th>FEHD</th><th>OpenStreetMap</th><th>Overture</th></tr></thead><tbody><tr><th>Link status</th><td>Sampling frame</td><td>${badge(x.sources.OSM.status)}</td><td>${badge(x.sources.Overture.status)}</td></tr>${row('name','Names')}${row('address','Address')}${row('phone','Phone')}${row('category','Category')}${row('opening_hours','Opening hours')}${row('operating_status','Operating status')}</tbody></table></div><p class="small-note">Other-source values above show each algorithm's top candidate, including uncertain candidates. FEHD category means licence type and is not cuisine. “Not supplied” does not mean a restaurant has no phone or is closed.</p><details open><summary>Provisional comparisons and denominators</summary><div class="table-wrap"><table><thead><tr><th>Field</th><th>FEHD / OSM</th><th>FEHD / Overture</th><th>OSM / Overture</th></tr></thead><tbody>${['name','address','phone','category','opening_hours','operating_status'].map(f=>`<tr><th>${esc(f.replaceAll('_',' '))}</th>${['FEHD vs OSM','FEHD vs Overture','OSM vs Overture'].map(p=>`<td>${badge(x.comparisons.find(c=>c.pair===p&&c.field===f)?.state||'Unavailable')}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p>Agree means equality under the specified normalisation. Disagree means the compared values differ; it does not prove an error. Only Agree and Disagree enter the provisional agreement denominator. These summaries depend on unvalidated links.</p></details>${['OSM','Overture'].map(src=>`<details><summary>${esc(src)} candidate evidence</summary>${x.sources[src].top_candidates.map(c=>`<div class="candidate"><strong>${esc(c.source_name)}</strong><span>${esc(c.source_address||'Address not supplied')}</span><span>Score ${c.score.toFixed(3)} · Name ${c.name_similarity.toFixed(3)} · Distance ${c.distance_m===null?'unavailable':Math.round(c.distance_m)+' m'}</span><span>ID ${esc(c.record_id)}</span>${src==='OSM'?`<a href="https://www.openstreetmap.org/${esc(c.record_id)}" target="_blank" rel="noreferrer">Open source record</a>`:''}</div>`).join('')||'<p>No candidate generated.</p>'}</details>`).join('')}<details><summary>FEHD location evidence</summary><p>${esc(b.coordinate_source||'No official coordinate counterpart located.')}</p><p>CSDI record update: ${esc(b.csdi_lastupdate||'not available')}. Coordinate proximity supports linkage but does not verify a branch's current operation.</p></details>`}
async function init(){try{const r=await fetch('data.json');if(!r.ok)throw Error('Snapshot unavailable');DATA=await r.json();const s=DATA.summary;$('#metrics').innerHTML=[[s.pilot_n,'pilot branches'],[s.sample_n,'provisional main branches'],[s.review_pair_n,'candidate pairs prepared'],[s.human_review_completed_n,'independently reviewed pairs']].map(([n,l])=>`<div class="metric"><strong>${n}</strong><span>${l}</span></div>`).join('');[...new Set(DATA.restaurants.map(x=>x.branch.district))].forEach(d=>{const o=document.createElement('option');o.value=o.textContent=d;$('#district').append(o)});$('#provenance').innerHTML=DATA.provenance.map(p=>`<p><strong>${esc(p.source)}</strong> — ${esc(p.description)}. Retrieved ${esc(p.retrieved_utc)}.</p>`).join('');['search','district','sample'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',renderList));renderList()}catch(e){$('#detail').textContent='The saved snapshot could not be loaded. '+e.message}}
init();
